// aliasesJSON preserves submitted aliases when the form re-renders.
func aliasesJSON(aliases []PageFormAliasView) string {
	type aliasEntry struct {
		Value string `json:"value"`
		ID    int64  `json:"id"`
	}
	entries := make([]aliasEntry, 0, len(aliases))
	for _, a := range aliases {
		entries = append(entries, aliasEntry{Value: a.Alias, ID: a.ID})
	}
	data, err := json.Marshal(entries)
	if err != nil {
		return "[]"
	}
	return string(data)
}

